import jax
import jax.numpy as jnp
from jax import grad, jit, vmap
from jax.experimental import optimizers

# Generate synthetic data
key = jax.random.PRNGKey(42)
X = jax.random.uniform(key, shape=(100, 1)) * 10
y = 2 * X + 3 + jax.random.normal(key, shape=(100, 1))

def learned_silu_forward(x, slope):
    return slope * x * jax.nn.sigmoid(x)

def learned_silu_backward(grad_output, x, slope):
    sigmoid_x = jax.nn.sigmoid(x)
    grad_input = grad_output * slope * (sigmoid_x + x * sigmoid_x * (1 - sigmoid_x))
    grad_slope = grad_output * x * sigmoid_x
    return grad_input, grad_slope

@jit
def model(params, x):
    slope = params['slope']
    return learned_silu_forward(x, slope)

@jit
def loss_fn(params, x, y):
    predictions = model(params, x)
    return jnp.mean((predictions - y) ** 2)

@jit
def update(params, grads):
    return optimizers.apply_updates(params, grads)

params = {'slope': jnp.array([1.0])}
opt_state = optimizers.init SGD(learning_rate=0.01)(params)

epochs = 1000
for epoch in range(epochs):
    grads = grad(loss_fn)(params, X, y)
    params, opt_state = update(params, grads)
    if (epoch + 1) % 100 == 0:
        print(f"Epoch [{epoch + 1}/{epochs}], Loss: {loss_fn(params, X, y):.4f}")

[w, b] = [params['slope'], 0]
print(f"Learned weight: {w:.4f}, Learned bias: {b:.4f}")

X_test = jnp.array([[4.0], [7.0]])
predictions = model(params, X_test)
print(f"Predictions for {X_test.tolist()}: {predictions.tolist()}")

